<?php $ph=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); ?>
<section class="payroll-tools"><h2><i class="fa-solid fa-file-invoice-dollar" aria-hidden="true"></i> My generated payslips</h2><p>Open a payslip below once Human Resource has generated it. Only your own payroll appears here.</p><div class="payroll-table-wrap"><table><thead><tr><th>Cutoff</th><th>Payout date</th><th>Net pay</th><th>View</th></tr></thead><tbody><?php foreach($history as $slip): ?><tr><td><?= $ph($slip['cutoff_start']) ?> to <?= $ph($slip['cutoff_end']) ?></td><td><?= $ph($slip['payout_date']) ?></td><td><?= $ph(money((float)$slip['net_pay'])) ?></td><td><a class="app-button secondary" href="<?= $ph(route($role.'.payroll').'?payslip_id='.(int)$slip['id']) ?>">View payslip</a></td></tr><?php endforeach ?><?php if(!$history): ?><tr><td colspan="4">No payslips have been generated for your account yet.</td></tr><?php endif ?></tbody></table></div></section>
